for(const entry of additions){const {phrases,words,en,...l}=entry;englishLanguages[l.id]=en;l.cards=[...phrases.map((x,i)=>makeAdditionalCard(x,'phrase',l.id+'-'+i)),...words.map((x,i)=>makeAdditionalCard(x,'word',l.id+'-word-'+i))];langs.push(l);if(l.source)sources.push([l.name+': expressões introdutórias',l.source,l.en?.[0]||en[0]+': introductory expressions']);}
function makeAdditionalCard([roman,pt,en,native],type,id){englishMeanings[pt]=en;return {id,roman,pt,native:native||roman,type,topic:type==='phrase'?'Primeiros encontros':'Essenciais'};}
